import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('returns a rejection for a missing required property without calling the executor [specs/hal-engine-tool-input-validation/spec.md#3]', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {name: 'weather', description: '', inputSchema: {type: 'object', required: ['location']}},
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );
    const result = await registry.execute('weather', {});
    expect({
      resultNamesRequiredLocation: /location.*required|required.*location/i.test(result.result),
      executorCalls,
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  it('names the property path and expected type for a wrong-typed value [specs/hal-engine-tool-input-validation/spec.md#4]', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: '',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const result = await registry.execute('weather', {location: 123});

    expect({
      namesPathAndType: /\/location.*string|string.*\/location/i.test(result.result),
      leaksValue: result.result.includes('123'),
      executorCalls,
    }).toEqual({namesPathAndType: true, leaksValue: false, executorCalls: 0});
  });

  it('passes a valid input and undeclared properties through unchanged [specs/hal-engine-tool-input-validation/spec.md#5]', async () => {
    const registry = new ToolRegistry();
    let received: Record<string, unknown> | undefined;
    registry.register(
      {name: 'weather', description: '', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}},
      async input => {
        received = input;
        return 'sunny';
      }
    );
    const input = {location: 'Berlin', extra: true};

    await registry.execute('weather', input);

    expect(received).toEqual(input);
  });

  it('throws for an unregistered tool name [specs/hal-engine-tool-input-validation/spec.md#6]', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('includes the parent path when a nested required property is missing [specs/hal-engine-tool-input-validation/spec.md#3]', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: '',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'object', required: ['city']}},
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const result = await registry.execute('weather', {location: {}});

    expect(result.result).toContain('/location/city');
  });

  it('formats nested required-property paths without an extra dot [specs/hal-engine-tool-input-validation/spec.md#3]', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: '',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'object', required: ['city']}},
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const result = await registry.execute('weather', {location: {}});

    expect(result.result).toContain('/location/city');
    expect(result.result).not.toContain('/location/.city');
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required, including its parent path when nested, and never invokes the executor. ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16), [validated by: returns a rejection for a missing required property without calling the executor](../../src/orchestration/tools/registry.test.ts#L4), [validated by: includes the parent path when a nested required property is missing](../../src/orchestration/tools/registry.test.ts#L68), [validated by: formats nested required-property paths without an extra dot](../../src/orchestration/tools/registry.test.ts#L88))
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value. ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by: names the property path and expected type for a wrong-typed value](../../src/orchestration/tools/registry.test.ts#L21))
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults. ([validated by: passes a valid input and undeclared properties through unchanged](../../src/orchestration/tools/registry.test.ts#L45))
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake. ([validated by: throws for an unregistered tool name](../../src/orchestration/tools/registry.test.ts#L62))

## Schema compilation and caching

- A static schema that cannot be compiled makes registration fail synchronously and names the tool. ([validated by: rejects an invalid static schema during registration](../../src/orchestration/tools/registry.registration.test.ts#L4))
- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
